import zipfile, os
from lxml import etree
ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with zipfile.ZipFile(os.environ['OUT_XLSX'], 'r') as z:
    sheet_xml = z.read('xl/worksheets/sheet1.xml')
    root = etree.fromstring(sheet_xml)
    for row in root.findall('.//m:row', ns):
        if row.get('r') in ('2','3'):
            for cell in row.findall('m:c', ns):
                if cell.get('r') in ('C2','D2','C3','D3'):
                    v = cell.find('m:v', ns)
                    print(cell.get('r'), 't=', cell.get('t'), 'v=', (v.text if v is not None else None))
    if 'xl/sharedStrings.xml' in z.namelist():
        ss = etree.fromstring(z.read('xl/sharedStrings.xml'))
        for i, si in enumerate(ss.findall('m:si', ns)):
            t = si.find('m:t', ns)
            if t is not None and t.text and 'N/A' in t.text:
                print('shared', i, repr(t.text))
